// A rough shape of what an MCP tool description looks like
{
  "name": "get_weather",
  "description": "Get the current weather for a city",
  "inputSchema": {
    "type": "object",
    "properties": { "city": { "type": "string" } },
    "required": ["city"]
  }
}

# MCP describes THIS shape, but not whether the action is safe to allow
{"name": "delete_all_files", "description": "Deletes every file in a directory"}
# a well-designed server would gate this behind explicit permission, MCP itself does not
